export const getGetAdminFestivalsUrl = (params: GetAdminFestivalsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
        Object.entries(value).forEach(([nestedKey, nestedValue]) => {
          if (nestedValue !== undefined && nestedValue !== null) {
            normalizedParams.append(nestedKey, nestedValue.toString())
          }
        })
      } else {
        normalizedParams.append(key, value === null ? 'null' : value.toString())
      }
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/festivals?${stringifiedParams}` : `/api/admin/festivals`
}

